// Corre una vez. Aplica las reglas de la state machine y emite un item por lead a actualizar.
const cfgRows = $('Get Config').all().map(i => i.json).filter(r => r.key);
const cfg = Object.fromEntries(cfgRows.map(r => [r.key, r.value]));
const leads = $('Get Leads').all().map(i => i.json).filter(l => l.id);

const today = new Date();
const iso = d => d.toISOString().slice(0, 10);
const daysSince = dateStr => {
  if (!dateStr) return 0;
  return Math.floor((today - new Date(dateStr)) / 86400000);
};
const fill = (tpl, lead) => String(tpl || '')
  .replace(/{{\s*first_name\s*}}/g, (lead.name || '').split(' ')[0])
  .replace(/{{\s*company\s*}}/g, lead.company || 'your company');

const updates = [];
for (const l of leads) {
  const since = daysSince(l.last_touch || l.sent_date);
  if (l.status === 'Contacted' && since >= 4) {
    updates.push({ id: l.id, fields: {
      draft_msg: fill(cfg.t2_touch, l), next_action: 'Send Touch 2', next_action_date: iso(today)
    }});
  } else if (l.status === 'T2 sent' && since >= 8) {
    updates.push({ id: l.id, fields: {
      draft_msg: fill(cfg.t3_breakup, l), next_action: 'Send Touch 3 (breakup)', next_action_date: iso(today)
    }});
  } else if (l.status === 'T3 sent' && since >= 3) {
    updates.push({ id: l.id, fields: {
      status: 'Dormant', next_action: '', next_action_date: null
    }});
  } else if (l.status === 'Proposal sent' && since === 3) {
    updates.push({ id: l.id, fields: {
      draft_msg: fill(cfg.proposal_followup_d3, l), next_action: 'Proposal check-in d3', next_action_date: iso(today)
    }});
  } else if (l.status === 'Proposal sent' && since >= 7) {
    updates.push({ id: l.id, fields: {
      draft_msg: fill(cfg.proposal_followup_d7, l), next_action: 'Proposal direct ask d7', next_action_date: iso(today)
    }});
  }
}

if (!updates.length) return [];
return updates.map(u => ({ json: {
  lead_id: u.id,
  draft_msg: u.fields.draft_msg ?? null,
  status: u.fields.status ?? null,
  next_action: u.fields.next_action ?? null,
  next_action_date: u.fields.next_action_date ?? null
}}));

// Prepara solo los campos no nulos para el update
const out = { lead_id: $json.lead_id, fields: {} };
for (const k of ['draft_msg','status','next_action','next_action_date']) {
  if ($json[k] !== null && $json[k] !== undefined) out.fields[k] = $json[k];
}
return { json: out };
